"""Explicit environmental explanations; no approval without official-source preflight."""
import json,sys
from pathlib import Path
rows={}
def add(key,overview,points,warning,case,variation,practice,term,meaning):
 rows[key]=dict(simples=overview,pontos=points,atencao=[warning],exemplo=case+' Variação: '+variation,prova=practice,
  termos=[dict(termo=term,significado=meaning)],remissoes=['https://www.planalto.gov.br/ccivil_03/leis/l9605.htm'])

add('art-34','O artigo pune pesca em período proibido ou local interditado e equipara outras condutas ligadas à pesca proibida. Exige identificar a regra competente sobre período, lugar, espécie, tamanho, quantidade ou método, sem presumir que toda pesca é criminosa.',
 ['Pena: detenção de 1 a 3 anos OU multa, ou ambas cumulativamente.', 'O parágrafo inclui espécies/tamanhos protegidos, quantidade ou método não permitido e a cadeia comercial dos espécimes provenientes de pesca proibida.'],
 'Conferir o ato do órgão competente e a data/local do fato. Não usar calendário de defeso desatualizado nem declarar insignificância ou condenação automática só pela quantidade.',
 'No período de proibição fixado pelo órgão competente para aquele local, uma pessoa realiza a pesca alcançada pela proibição.',
 'Se o período está permitido, isso afasta apenas essa hipótese; ainda se verificam tamanho, espécie, quantidade, método e outras vedações.',
 ['A pena exige sempre detenção E multa? Não; o caput admite detenção ou multa, ou ambas.', 'Transportar espécimes provenientes da pesca proibida fica fora do artigo? Não; o parágrafo único, III inclui essa conduta.'],
 'Período proibido','Recorte temporal da proibição de pesca fixada pela autoridade competente.')
add('art-35','O foco é o meio empregado na pesca: explosivos, substâncias com efeito semelhante na água, tóxicos ou outro meio proibido pela autoridade competente. A escolha do método pode configurar o tipo mesmo sem a proibição de calendário do art. 34.',
 ['Pena: reclusão de 1 a 5 anos.', 'Explosivos e substâncias tóxicas são hipóteses expressas; outros meios exigem a proibição competente.'],
 'Não copiar a pena alternativa do art. 34 para este artigo. Descrever o método e seus elementos; não inventar proibição técnica que não foi consultada.',
 'Um pescador utiliza explosivo para pescar durante período normalmente permitido.',
 'O uso de um método permitido afasta essa hipótese, mas não torna regular uma pesca em local interditado ou fora dos demais limites.',
 ['O período permitido afasta a proibição de pescar com explosivo? Não; o artigo trata do meio empregado.', 'A pena prevista é detenção ou multa do art. 34? Não; aqui o texto prevê reclusão de 1 a 5 anos.'],
 'Meio proibido','Método de pesca vedado expressamente ou por autoridade competente.')
add('art-36','A definição legal de pesca abrange atos tendentes a retirar ou capturar peixes, crustáceos, moluscos e vegetais hidróbios. A finalidade econômica não é requisito dessa definição, que contém ressalva sobre espécies ameaçadas nas listas oficiais.',
 ['Inclui retirada, extração, coleta, apanha, apreensão e captura, como atos tendentes.', 'Abrange espécimes suscetíveis OU não de aproveitamento econômico; observar a ressalva das listas oficiais.'],
 'Definição não é condenação automática: devem ser verificados o tipo incriminador, a conduta e seus pressupostos. A ressalva das espécies ameaçadas não significa autorização para capturá-las.',
 'A questão exclui da definição a coleta de moluscos porque não haveria venda.',
 'Se a espécie está na lista oficial de ameaçadas, analisar a ressalva e o regime específico, sem transformá-la em permissão de captura.',
 ['A definição depende de venda dos espécimes? Não; abrange aproveitamento econômico ou não.', 'A ressalva sobre espécies ameaçadas autoriza capturá-las livremente? Não; exige examinar sua proteção específica.'],
 'Vegetais hidróbios','Vegetais associados ao meio aquático incluídos na definição legal de pesca.')
add('art-37','O artigo descreve hipóteses em que o abate de animal não constitui crime: necessidade para saciar fome, proteção autorizada de lavouras/pomares/rebanhos e animal caracterizado como nocivo pelo órgão competente. Cada hipótese tem seus próprios requisitos.',
 ['Fome: estado de necessidade para o agente OU sua família.', 'Proteção de lavoura: autorização legal e expressa; nocividade: caracterização pelo órgão competente.', 'O inciso III está vetado.'],
 'Alegação particular de perigo ou prejuízo não substitui as condições expressas. Não estender esta regra a abate automático de animal apreendido: preservar a ressalva da ADPF 640 no art. 25.',
 'Para proteger seu pomar, uma pessoa abate animal sem a autorização legal e expressa exigida pelo inciso II.',
 'Com autorização válida, examina-se a hipótese do inciso II; se a justificativa for nocividade, é necessária a caracterização pelo órgão competente do inciso IV.',
 ['A proteção do pomar dispensa autorização? Não; o inciso II exige autorização legal e expressa.', 'Basta o particular declarar que o animal é nocivo? Não; o inciso IV exige caracterização pelo órgão competente.'],
 'Autorização expressa','Ato competente exigido para a hipótese de proteção de lavouras, pomares e rebanhos.')
add('art-38','Protege floresta considerada de preservação permanente, inclusive em formação, contra destruição, dano ou utilização contrária às normas de proteção. Identificar a floresta e seu regime, distinguindo esse tipo de outras infrações relativas a APP.',
 ['Pena: detenção de 1 a 3 anos OU multa, ou ambas.', 'Modalidade culposa: redução da pena à metade.'],
 'Não reduzir toda APP a floresta nem afirmar que qualquer intervenção em qualquer vegetação configura exatamente este artigo. O tipo exige o objeto e a conduta previstos.',
 'É danificada dolosamente uma floresta de preservação permanente que ainda está em formação.',
 'Se os pressupostos da modalidade culposa forem demonstrados, aplica-se a redução à metade prevista no parágrafo, não a mesma resposta dolosa sem qualificação.',
 ['Floresta em formação está fora do tipo? Não; é expressamente abrangida.', 'O crime culposo mantém integralmente a pena prevista? Não; o parágrafo determina redução à metade.'],
 'Floresta em formação','Objeto protegido pelo artigo mesmo antes de alcançar desenvolvimento completo.')
add('art-38-a','O tipo protege vegetação primária ou secundária em estágio avançado ou médio de regeneração do Bioma Mata Atlântica. Pune destruição, dano e utilização que infrinja as normas de proteção; o estágio deve ser tecnicamente identificado.',
 ['Pena: detenção de 1 a 3 anos OU multa, ou ambas.', 'Culpa: pena reduzida à metade; recorte de bioma e estágio é essencial.'],
 'Vegetação em estágio inicial não se insere automaticamente na redação deste tipo; isso não significa ausência de qualquer proteção ou infração por outros dispositivos.',
 'O laudo caracteriza vegetação secundária em estágio médio do Bioma Mata Atlântica e a conduta infringe sua proteção.',
 'Se o estágio é inicial, reavaliar o enquadramento em vez de simplesmente repetir a hipótese do art. 38-A ou afirmar licitude universal.',
 ['O artigo limita-se à vegetação primária? Não; inclui secundária em estágio avançado ou médio.', 'Culpa tem previsão expressa? Sim; o parágrafo prevê redução à metade.'],
 'Estágio de regeneração','Classificação da vegetação relevante para o recorte de incidência deste tipo.')
add('art-39','O artigo pune o corte de árvores em floresta considerada de preservação permanente sem permissão da autoridade competente. O candidato deve identificar conjuntamente o corte, o objeto protegido e a ausência da permissão pertinente.',
 ['Pena: detenção de 1 a 3 anos OU multa, ou ambas.', 'Corte sem permissão é o núcleo específico; não confundir com o tipo mais amplo do art. 38.'],
 'Não importar automaticamente para este artigo a modalidade culposa do art. 38. A permissão deve ser competente, válida e pertinente; documento alheio ao fato não satisfaz o requisito.',
 'Uma pessoa corta árvores na floresta de preservação permanente sem a permissão exigida.',
 'Se há permissão competente que efetivamente abrange a intervenção, a ausência de permissão desse tipo não está demonstrada; outras condições continuam relevantes.',
 ['Qual ato é especificamente descrito? Cortar árvores na floresta protegida sem permissão competente.', 'A pena necessariamente acumula detenção e multa? Não; admite alternativas ou cumulação.'],
 'Permissão competente','Permissão aplicável emitida pela autoridade com competência para a intervenção.')
add('art-40','Pune dano direto ou indireto às unidades de conservação e às áreas indicadas no artigo. A enumeração das unidades de proteção integral e a agravante referente a espécies ameaçadas devem ser lidas no seu recorte próprio.',
 ['Pena: reclusão de 1 a 5 anos; dano pode ser direto OU indireto.', 'Dano a espécies ameaçadas em unidade de proteção integral é agravante do §2º.', 'Culpa: pena reduzida à metade.'],
 'O §2º é circunstância agravante, não fração fixa inventada. Não confundir os parágrafos atuais do art. 40 com o caput vetado e trechos residuais do art. 40-A.',
 'Uma atividade fora da unidade causa dano indireto comprovado à unidade de conservação.',
 'A mudança para conduta culposa exige aplicar o §3º e seus pressupostos; a localização fora da unidade não afasta automaticamente o dano indireto.',
 ['Só dano praticado fisicamente dentro da unidade é abrangido? Não; a redação inclui dano indireto, independentemente da localização.', 'A agravante do §2º fixa aumento automático de metade? Não; não contém essa fração.'],
 'Dano indireto','Dano que alcança o objeto protegido por repercussão da conduta, com vínculo demonstrado.')
add('art-41','Após a Lei 14.944/2024, o artigo abrange incêndio em floresta ou nas demais formas de vegetação. O tipo não se restringe à antiga expressão mata ou floresta e distingue as penas das modalidades dolosa e culposa.',
 ['Dolo: reclusão de 2 a 4 anos E multa.', 'Culpa: detenção de 6 meses a 1 ano E multa.', 'Objeto ampliado pela redação de 2024: floresta OU demais formas de vegetação.'],
 'Não apresentar fogo legalmente autorizado ou toda queima como crime automático. Verificar conduta, elemento subjetivo, permissões e regime de manejo integrado do fogo.',
 'O agente provoca dolosamente incêndio em forma de vegetação que não é floresta, em situação que preenche os pressupostos do tipo.',
 'Se o fato é culposo, a pena é a do parágrafo: detenção de 6 meses a 1 ano e multa, não a reclusão do caput.',
 ['A redação atual alcança apenas floresta? Não; também as demais formas de vegetação.', 'A modalidade culposa prevê reclusão de 2 a 4 anos? Não; prevê detenção de 6 meses a 1 ano e multa.'],
 'Demais formas de vegetação','Ampliação textual do objeto de proteção feita em 2024.')
add('art-42','O tipo abrange fabricar, vender, transportar ou soltar balões capazes de provocar incêndios nos ambientes indicados. A capacidade de provocar incêndio é requisito; a redação não exige que o incêndio efetivamente aconteça.',
 ['Condutas alternativas: fabricar, vender, transportar OU soltar.', 'Pena: detenção de 1 a 3 anos OU multa, ou ambas.', 'Abrange florestas, outras vegetações, áreas urbanas e assentamentos humanos.'],
 'Não tratar qualquer balão decorativo como objeto do crime sem sua capacidade incendiária. Também não restringir o tipo à pessoa que o solta.',
 'Uma pessoa transporta balão capaz de provocar incêndio e afirma que o artigo só alcança quem o solta.',
 'Se o objeto é mero balão decorativo incapaz de provocar incêndio, não está demonstrado esse requisito; a conclusão depende do objeto real.',
 ['Só soltar é conduta prevista? Não; fabricação, venda e transporte também constam.', 'É necessário demonstrar a capacidade de provocar incêndio? Sim; é característica expressa do objeto.'],
 'Capacidade incendiária','Aptidão do balão para provocar os incêndios descritos no artigo.')
add('art-44','Pune extração de pedra, areia, cal ou minerais de florestas de domínio público ou consideradas de preservação permanente, sem prévia autorização. O tipo combina o local protegido, a atividade extrativa e a falta do ato autorizativo.',
 ['Pena: detenção de 6 meses a 1 ano E multa.', 'A autorização deve ser prévia; o objeto inclui qualquer espécie de minerais.'],
 'Não confundir com o regime geral de mineração do art. 55 nem afirmar concurso automático de crimes. Identificar os tipos e a relação das condutas no caso concreto.',
 'Areia é extraída da floresta de domínio público sem autorização prévia.',
 'Se há autorização competente anterior abrangendo a extração, verificar suas condições; alegar que pedirá autorização depois não equivale à autorização prévia.',
 ['A extração de areia está abrangida? Sim; é expressamente indicada.', 'Pedir autorização depois satisfaz a exigência prévia? Não; o ato exigido antecede a intervenção.'],
 'Extração','Retirada de minerais do local protegido nas condições descritas pelo tipo.')
add('art-45','O objeto é madeira de lei classificada por ato do Poder Público. Cortá-la ou transformá-la em carvão em desacordo com determinações legais é abrangido para exploração econômica ou não, inclusive fins industriais e energéticos.',
 ['Pena: reclusão de 1 a 2 anos E multa.', 'A classificação por ato público é requisito do objeto; a finalidade não precisa ser econômica.'],
 'Não identificar madeira de lei apenas pelo preço comercial ou pela opinião do agente. O ato classificatório e as determinações legais precisam ser verificados.',
 'Madeira oficialmente classificada é transformada em carvão, contrariando as determinações legais, para uso sem venda.',
 'Se não há classificação do objeto como madeira de lei por ato público, não se presume o requisito específico; verificar outros tipos eventualmente aplicáveis.',
 ['Venda é requisito indispensável? Não; a exploração pode ser econômica ou não.', 'Qualquer madeira cara é automaticamente madeira de lei? Não; o artigo exige classificação por ato do Poder Público.'],
 'Madeira de lei','Madeira assim classificada por ato do Poder Público para este tipo.')
add('art-46','Na aquisição comercial ou industrial de produtos vegetais, o artigo exige licença do vendedor e a via que deve acompanhar o produto até o beneficiamento final. O parágrafo também alcança venda, depósito, transporte e guarda sem licença válida.',
 ['Pena: detenção de 6 meses a 1 ano E multa.', 'A licença deve cobrir todo o tempo da viagem ou armazenamento nas condutas do parágrafo.', 'A aquisição do caput tem finalidade comercial ou industrial.'],
 'Nota fiscal não substitui automaticamente o documento ambiental exigido. Verificar o sistema e os documentos aplicáveis ao produto e ao percurso, sem inventar dispensa genérica.',
 'Uma empresa adquire madeira comercialmente sem exigir a licença do vendedor e sem a via documental exigida.',
 'Uma licença existe, mas não é válida durante toda a viagem; a mera existência do documento não satisfaz a condição temporal do parágrafo.',
 ['A finalidade do caput é qualquer aquisição, sem recorte? Não; o texto indica fins comerciais ou industriais.', 'Licença vencida durante a viagem atende ao parágrafo? Não; deve ser válida para todo o período.'],
 'Licença válida','Documento competente com alcance material e temporal pertinente ao produto e à atividade.')
add('art-48','O núcleo é impedir ou dificultar a regeneração natural de florestas ou outras formas de vegetação. Não se limita ao ato inicial de derrubada: a manutenção de obstáculo à recuperação pode exigir análise própria.',
 ['Pena: detenção de 6 meses a 1 ano E multa.', 'Impedir OU dificultar são condutas distintas; o objeto não se restringe a floresta.'],
 'Não presumir o crime apenas pela ausência de vegetação: é preciso identificar a conduta e seus elementos. Questões de permanência e prescrição dependem do caso e de jurisprudência específica.',
 'São mantidos obstáculos que, nas circunstâncias comprovadas, impedem a regeneração natural de uma vegetação protegida.',
 'Se não há conduta impeditiva ou dificultadora demonstrada, uma fotografia isolada do solo não autoriza concluir automaticamente todos os elementos.',
 ['É indispensável que o agente tenha feito o desmatamento inicial? O núcleo deste artigo é impedir ou dificultar regeneração; a análise não se esgota na autoria da derrubada.', 'A norma protege apenas floresta? Não; inclui outras formas de vegetação.'],
 'Regeneração natural','Recuperação da vegetação que pode ser impedida ou dificultada pela conduta.')
add('art-49','Protege plantas ornamentais em logradouros públicos ou propriedade privada alheia. Além da modalidade culposa, a Lei 15.299/2025 acrescentou hipótese específica de corte ou poda tacitamente autorizados após requerimento com risco de acidente atestado e falta de resposta fundamentada.',
 ['Dolo: detenção de 3 meses a 1 ano OU multa, ou ambas.', 'Culpa: detenção de 1 a 6 meses OU multa.', '§2º: requerimento, risco atestado por profissional/empresa habilitado e 45 dias sem resposta fundamentada são requisitos da hipótese.'],
 'O silêncio não cria licença universal para qualquer corte. Preservar o recorte do art. 49 e conferir outras proteções e autorizações pertinentes; a regra recente não é autorização para desmatar qualquer área.',
 'O requerente pede poda por risco de acidente atestado por profissional habilitado e o órgão responsável não responde fundamentadamente em 45 dias, na hipótese descrita pelo §2º.',
 'Se falta o atestado exigido, não basta contar 45 dias: a hipótese legal não está integralmente demonstrada.',
 ['Qualquer pedido sem resposta autoriza qualquer corte? Não; há requisitos materiais e documentais específicos.', 'A regra dos 45 dias elimina a necessidade do atestado? Não; o risco deve ser devidamente atestado por profissional ou empresa habilitado.'],
 'Autorização tácita específica','Hipótese condicionada do §2º; não autorização geral para intervenção em vegetação.')
add('art-50','Pune destruição ou dano de florestas nativas ou plantadas e de vegetação fixadora de dunas ou protetora de mangues, objeto de especial preservação. A especial proteção e a identificação do objeto importam para o enquadramento.',
 ['Pena: detenção de 3 meses a 1 ano E multa.', 'Floresta plantada não é excluída só por sua origem; verificar a especial preservação.'],
 'Não confundir com o art. 50-A: domínio público/devoluto e subsistência têm regime próprio. Também não presumir que qualquer plantação preenche este tipo.',
 'É destruída vegetação fixadora de dunas objeto de especial preservação.',
 'Se o caso é floresta plantada, não descartá-lo só pela origem; verificar se o objeto e sua proteção correspondem ao artigo.',
 ['Somente floresta nativa pode ser objeto do artigo? Não; a redação inclui plantada, observados seus requisitos.', 'A pena do texto prevê multa cumulativa? Sim; indica detenção e multa.'],
 'Especial preservação','Regime de proteção relevante para identificar o objeto do tipo.')
add('art-50-a','O tipo trata de desmatamento, exploração econômica ou degradação de floresta em terras públicas ou devolutas, sem autorização. Há ressalva para subsistência imediata e aumento de pena por extensão superior a mil hectares.',
 ['Pena: reclusão de 2 a 4 anos E multa.', '§1º: subsistência imediata pessoal do agente OU da família.', '§2º: acima de 1.000 ha, aumento de 1 ano por milhar de hectare.'],
 'Não estender a ressalva a exploração comercial apenas porque gera renda familiar. Não inventar fórmula de arredondamento de frações de hectare que o texto não resolve.',
 'Uma exploração comercial degrada floresta em terra pública sem autorização; o agente invoca genericamente que mantém sua família.',
 'Uma conduta efetivamente necessária à subsistência imediata pessoal ou familiar exige analisar a ressalva própria, sem equipará-la a toda atividade rentável.',
 ['A ressalva é qualquer renda obtida para a família? Não; exige necessidade de subsistência imediata.', 'Exatamente 1.000 ha é superior a 1.000 ha? Não; a condição textual do §2º é extensão superior.'],
 'Subsistência imediata','Necessidade pessoal ou familiar no recorte do §1º, não justificativa comercial genérica.')
add('art-51','O artigo abrange comercialização de motosserra ou sua utilização em florestas e outras vegetações sem licença ou registro da autoridade competente. O candidato deve observar as condutas e o documento exigido no regime pertinente.',
 ['Pena: detenção de 3 meses a 1 ano E multa.', 'Comercializar é conduta expressa, além da utilização descrita.'],
 'Não substituir o requisito ambiental por simples recibo de compra nem afirmar que qualquer posse de motosserra é o núcleo deste artigo.',
 'O agente utiliza motosserra na vegetação sem o documento ambiental exigido, apresentando apenas o recibo da loja.',
 'Com licença/registro competente pertinente, a ausência documental não está demonstrada; a regularidade da ferramenta não autoriza por si qualquer corte de árvores.',
 ['Recibo comercial equivale automaticamente a licença ambiental? Não; são documentos e finalidades diferentes.', 'O texto limita-se à utilização? Não; também contempla comercialização.'],
 'Registro competente','Registro exigido pelo regime da autoridade competente para a atividade com motosserra.')
add('art-52','O artigo pune entrada em unidade de conservação conduzindo substâncias ou instrumentos próprios à caça ou exploração de produtos florestais sem licença competente. Identificar o instrumento, a entrada e a falta da licença na hipótese descrita.',
 ['Pena: detenção de 6 meses a 1 ano E multa.', 'O texto descreve penetrar na unidade; não exige narrar abate consumado como requisito adicional de sua redação.'],
 'Nem todo objeto de uso cotidiano é automaticamente instrumento próprio para as atividades indicadas. Verificar características, contexto e licença, sem presumir culpabilidade pela simples visita.',
 'O agente entra na unidade conduzindo instrumentos próprios para caça, sem a licença competente.',
 'Um visitante sem instrumentos próprios à caça/exploração não é automaticamente enquadrado só porque entrou na unidade; examinar os elementos concretos.',
 ['O artigo exige relato de abate consumado? Sua redação descreve a entrada com os instrumentos/substâncias sem licença; não exige esse resultado adicional.', 'Toda visita à unidade configura o tipo? Não; há requisitos específicos de objeto, conduta e licença.'],
 'Instrumento próprio','Instrumento relacionado à caça ou exploração florestal na hipótese do artigo.')
add('art-53','É causa de aumento aplicável aos crimes da seção de flora, quando ocorrem os resultados ou circunstâncias enumerados. Não cria um crime independente nem se aplica indistintamente a todos os crimes da lei.',
 ['Aumento: 1/6 a 1/3.', 'Inclui diminuição de águas, erosão ou alteração climática e circunstâncias como sementes, formação da vegetação, seca/inundação, noite, domingo ou feriado.', 'Espécie ameaçada somente no local também está contemplada.'],
 'Não aplicar automaticamente causas de aumento semelhantes cumulativamente pelo mesmo fato. Identificar o crime-base, a circunstância e eventual vedação de dupla valoração.',
 'Um crime da seção de flora ocorre contra espécie ameaçada apenas naquele local, com a circunstância demonstrada.',
 'Se a questão trata de crime de outra seção, não transportar o aumento automaticamente: o caput limita seu alcance aos crimes desta seção.',
 ['A ameaça precisa abranger todo o país? Não; o inciso II, c admite ameaça somente no local da infração.', 'A fração é sempre metade? Não; é de um sexto a um terço.'],
 'Causa de aumento','Regra que eleva a pena do crime-base nas condições legais, sem criar tipo autônomo.')

first_keys=set(rows)
add('art-54','O tipo de poluição exige os níveis e resultados ou potencialidade previstos, não qualquer alteração ambiental. O artigo distingue forma básica, culpa, formas qualificadas e omissão das medidas de precaução exigidas pela autoridade competente.',
 ['Caput: reclusão de 1 a 4 anos E multa; culpa: detenção de 6 meses a 1 ano E multa.', '§2º: reclusão de 1 a 5 anos nas hipóteses qualificadas.', '§3º: omissão de medidas exigidas em risco de dano grave ou irreversível recebe as penas do §2º.'],
 'Não presumir dano consumado como único caminho do caput: a potencialidade de dano à saúde é expressa. A prova dos elementos e a necessidade de exame técnico devem ser analisadas no caso, sem inventar dispensa universal de perícia.',
 'Poluição hídrica torna necessária a interrupção do abastecimento público de água de uma comunidade.',
 'Se não há essa interrupção, não se conclui ausência de todo crime: examinar os elementos do caput ou de outra hipótese, com prova adequada.',
 ['A interrupção do abastecimento público está no §2º? Sim; no inciso III.', 'O §3º exige uma medida de precaução cobrada pela autoridade competente? Sim; não descreve qualquer omissão genérica.'],
 'Nível de poluição','Patamar relevante para os resultados ou potencialidade descritos no tipo.')
add('art-55','A norma pune pesquisa, lavra ou extração mineral sem o ato competente ou em desacordo com o obtido. O parágrafo inclui a falta de recuperação da área nos termos do ato autorizativo ou da determinação competente.',
 ['Pena: detenção de 6 meses a 1 ano E multa.', 'Ter licença não basta se a execução contrariar suas condições.', 'A recuperação da área é obrigação penalmente relevante na hipótese do parágrafo.'],
 'Não confundir pesquisa mineral com simples estudo bibliográfico. Licenças e competências concretas precisam ser identificadas; não se presume concurso com outros crimes pela mesma palavra extração.',
 'Uma lavra possui autorização, mas opera deliberadamente em desacordo com suas condições.',
 'A lavra encerra e o responsável deixa de recuperar a área conforme a determinação competente: o parágrafo tem hipótese própria.',
 ['A existência do documento elimina toda hipótese do caput? Não; executar em desacordo com ele também está descrito.', 'A omissão de recuperar a área aparece no artigo? Sim; o parágrafo a equipara nas condições previstas.'],
 'Lavra','Atividade de aproveitamento de recursos minerais no regime autorizativo pertinente.')
add('art-56','Pune atividades com produto ou substância tóxica, perigosa ou nociva em desacordo com lei ou regulamento. Também alcança abandono e tratamento irregular de resíduos perigosos, com disciplina de culpa e de material nuclear ou radioativo.',
 ['Dolo: reclusão de 1 a 4 anos E multa; culpa: detenção de 6 meses a 1 ano E multa.', 'Material nuclear/radioativo: aumento de 1/6 a 1/3.', 'O §1º inclui resíduos perigosos e abandono ou uso contrário às normas.'],
 'Identificar a periculosidade e a exigência legal/regulamentar violada. Produto perigoso não torna ilícita toda operação autorizada; não importar uma lista química desatualizada como proibição universal.',
 'Resíduo perigoso é armazenado deliberadamente de modo diverso do estabelecido na regulamentação aplicável.',
 'Se o fato é culposo e preenche essa modalidade, utilizar a pena do §3º, não a reclusão do caput.',
 ['Resíduos perigosos estão fora da redação? Não; o §1º, II inclui sua manipulação, transporte e destinação irregular.', 'Material radioativo eleva a pena por fração expressa? Sim; de um sexto a um terço.'],
 'Resíduo perigoso','Resíduo sujeito às exigências pertinentes que integram o tipo, com sua natureza demonstrada.')
add('art-58','Prevê aumentos para crimes dolosos da seção de poluição e outros crimes ambientais, conforme o resultado. A regra tem condição de subsidiariedade: aplica-se somente se do fato não resultar crime mais grave.',
 ['Dano irreversível: 1/6 a 1/3; lesão corporal grave: 1/3 até metade.', 'Morte: aumento até o dobro, não dobro obrigatório.', 'O caput limita a regra aos crimes dolosos desta seção.'],
 'Não aplicar este aumento automaticamente a crimes culposos ou ignorar o crime mais grave mencionado no parágrafo. Resultados e vínculo com a conduta exigem demonstração.',
 'Crime doloso dessa seção causa dano ambiental irreversível, sem configurar crime mais grave na hipótese analisada.',
 'Se o crime-base é culposo, não aplicar automaticamente o art. 58: o caput refere-se a crimes dolosos.',
 ['A morte sempre obriga dobrar exatamente a pena? Não; a redação diz até o dobro.', 'O dispositivo afasta a análise de crime mais grave? Não; o parágrafo condiciona sua aplicação.'],
 'Subsidiariedade','Aplicação condicionada à inexistência de crime mais grave resultante do fato, nos termos do parágrafo.')
add('art-60','Na redação compilada após a Lei 15.190/2025, o tipo trata de construir, reformar, ampliar, instalar ou fazer funcionar empreendimento potencialmente poluidor sem ato ambiental competente ou contrariando as normas. A pena foi alterada e há aumento ligado à sujeição ao EIA.',
 ['Redação de 2025: detenção de 6 meses a 2 anos OU multa, ou ambas.', 'Parágrafo: aumento até o dobro se o licenciamento é sujeito ao Estudo Prévio de Impacto Ambiental.', 'A Lei 15.190 prevê vacância de 180 dias; publicação original e produção de efeitos não são a mesma data.'],
 'Não ensinar a antiga pena de 1 a 6 meses como redação atual compilada. A lei geral de licenciamento é objeto de controle no STF; a notícia de ajuizamento não resolve as ADIs nem permite afirmar suspensão universal. Aplicação temporal e decisão pertinente exigem consulta específica.',
 'A questão pede a pena do art. 60 na redação compilada conferida em 2026, e apresenta somente 1 a 6 meses.',
 'Se o fato ocorreu antes da produção de efeitos da mudança, analisar a lei penal no tempo; a nova pena mais gravosa não retroage apenas por constar hoje no compilado.',
 ['A redação compilada de 2025 mantém 1 a 6 meses? Não; prevê 6 meses a 2 anos, ou multa, ou ambas.', 'Até o dobro significa aumento necessariamente igual ao dobro? Não; o parágrafo usa limite máximo, condicionado à sujeição ao EIA.'],
 'EIA','Estudo Prévio de Impacto Ambiental; sua exigência é pressuposto do aumento descrito.')
add('art-61','O artigo protege agricultura, pecuária, fauna, flora e ecossistemas contra disseminação de doença, praga ou espécies que possam causar dano. É preciso identificar a disseminação e a capacidade danosa, sem tratar qualquer introdução de organismo como crime automático.',
 ['Pena: reclusão de 1 a 4 anos E multa.', 'Doença, praga OU espécies potencialmente danosas são objetos previstos.'],
 'A possibilidade de causar dano é elemento expresso; a classificação técnica e os demais elementos precisam de demonstração. Não criar modalidade culposa sem previsão.',
 'É disseminada espécie cuja capacidade de dano ao ecossistema está tecnicamente identificada, nas circunstâncias que preenchem o tipo.',
 'Sem prova da capacidade danosa e dos demais elementos, não concluir o crime só porque se trata de espécie nova naquele local.',
 ['O dano precisa sempre já ter acontecido? O artigo se refere a espécies que possam causar dano; a capacidade é elemento da redação.', 'Só agricultura e pecuária são protegidas? Não; também fauna, flora e ecossistemas.'],
 'Disseminação','Propagação do agente ou espécie nas condições previstas pelo tipo.')
add('art-62','Pune destruir, inutilizar ou deteriorar bem especialmente protegido e os acervos ou instalações especificados. A proteção pode decorrer de lei, ato administrativo ou decisão judicial; há pena própria para a modalidade culposa.',
 ['Dolo: reclusão de 1 a 3 anos E multa.', 'Culpa: detenção de 6 meses a 1 ano, sem prejuízo da multa.', 'Arquivo, biblioteca e instalação científica protegidos constam do inciso II.'],
 'Não exigir sempre tombamento formal como único modo de proteção: o texto também indica lei, ato administrativo ou decisão judicial. Verificar o objeto efetivamente protegido.',
 'É destruído arquivo especialmente protegido por decisão judicial.',
 'Se o fato é culposo, a pena é a do parágrafo; não transportar a reclusão dolosa nem ignorar a multa.',
 ['A proteção pode decorrer de decisão judicial? Sim; é fonte expressa nos dois incisos.', 'Culpa afasta automaticamente toda punição? Não; há previsão específica no parágrafo.'],
 'Bem especialmente protegido','Objeto cuja proteção pertinente foi estabelecida por lei, ato administrativo ou decisão judicial.')
add('art-63','Pune alterar aspecto ou estrutura de edificação ou local especialmente protegido por seu valor indicado, sem autorização ou em desacordo com ela. Não é necessário descrever destruição completa para a conduta de alteração prevista.',
 ['Pena: reclusão de 1 a 3 anos E multa.', 'Proteção pode decorrer de lei, ato administrativo OU decisão judicial.', 'Autorização existente não abrange alterações que a contrariem.'],
 'Não confundir a alteração deste artigo com a destruição do art. 62. Identificar a especial proteção e o ato autorizativo, sem presumir que toda reforma é criminosa.',
 'A fachada de edificação protegida por valor histórico é alterada em desacordo com a autorização concedida.',
 'Uma intervenção efetivamente abrangida pela autorização não demonstra a hipótese de falta ou desacordo; outras exigências continuam relevantes.',
 ['É preciso destruir totalmente a edificação? Não; o núcleo é alterar aspecto ou estrutura nas condições previstas.', 'Possuir qualquer autorização elimina o tipo? Não; a alteração em desacordo com a concedida também consta.'],
 'Alteração de aspecto','Modificação visual relevante ao bem protegido nas condições do artigo.')
add('art-64','Pune promover construção em solo não edificável ou seu entorno, quando esse regime decorre dos valores protegidos indicados, sem autorização ou em desacordo com a concedida. A não edificabilidade e a proteção pertinente são elementos do recorte.',
 ['Pena: detenção de 6 meses a 1 ano E multa.', 'O texto inclui o entorno e enumera valores como paisagístico, ecológico, histórico e cultural.'],
 'Não concluir o crime a partir de qualquer irregularidade de obra ou de qualquer solo sem alvará. Identificar a não edificabilidade por motivo indicado e a autorização competente.',
 'É promovida construção em solo não edificável por seu valor arqueológico, sem a autorização competente.',
 'Em obra irregular em terreno comum, não presumir este mesmo enquadramento sem o regime protegido específico; verificar os tipos e normas pertinentes.',
 ['O entorno é sempre excluído? Não; está expressamente indicado no tipo.', 'Qualquer falta de alvará preenche necessariamente este artigo? Não; o solo e a proteção precisam corresponder ao recorte legal.'],
 'Solo não edificável','Solo submetido à condição descrita em razão dos valores protegidos pelo tipo.')
add('art-65','A pichação ou outra conspurcação de edificação ou monumento urbano é punida, com pena específica para bem tombado pelo valor indicado. Grafite artístico pode não constituir crime, mas a ressalva exige consentimento/autorização e observância das normas pertinentes.',
 ['Caput: detenção de 3 meses a 1 ano E multa.', 'Bem tombado nas hipóteses do §1º: detenção de 6 meses a 1 ano E multa.', 'Grafite: objetivo de valorização artística e condições do §2º.'],
 'Finalidade artística alegada não substitui consentimento do proprietário e, quando cabível, locatário/arrendatário; em bem público exige-se autorização competente e observância das regras.',
 'Grafite de valorização artística é realizado em bem público com autorização competente e atendimento das normas pertinentes.',
 'Sem a autorização pública exigida, não basta chamar a intervenção de arte para preencher a ressalva do §2º.',
 ['Todo grafite é automaticamente lícito? Não; o §2º contém requisitos cumulativos conforme o bem.', 'No bem público basta consentimento de um particular? Não; exige autorização do órgão competente.'],
 'Grafite autorizado','Manifestação artística que preenche a finalidade e as condições legais da ressalva.')
add('art-66','O artigo trata do funcionário público que faz afirmação falsa ou enganosa, omite verdade ou sonega informação técnico-científica em procedimento de autorização ou licenciamento ambiental. O papel do agente e o contexto do procedimento são essenciais.',
 ['Pena: reclusão de 1 a 3 anos E multa.', 'Omissão da verdade e sonegação também são condutas previstas.'],
 'Não aplicar indistintamente a qualquer particular a condição de funcionário público deste tipo; participação e outros crimes exigem análise própria. Estudo falso também tem disciplina do art. 69-A.',
 'Funcionário público omite informação técnico-científica relevante no procedimento ambiental em hipótese que preenche o tipo.',
 'Se o fato é elaboração de estudo falso por particular, examinar o art. 69-A e eventual participação, em vez de ignorar o sujeito e o procedimento exigidos aqui.',
 ['O artigo só alcança mentira expressamente escrita? Não; inclui omitir a verdade e sonegar informações.', 'O contexto é qualquer conversa privada? Não; a redação delimita procedimentos de autorização ou licenciamento ambiental.'],
 'Sonegação de informação','Ocultação da informação técnico-científica no procedimento previsto.')
add('art-67','A Lei 15.190/2025 passou a descrever expressamente a concessão dolosa, por funcionário público, de licença, autorização ou permissão que sabe contrariar as normas ambientais. O parágrafo de modalidade culposa foi revogado na redação compilada.',
 ['Redação atual compilada: detenção de 1 a 3 anos E multa.', 'Exige concessão dolosa e ciência do desacordo; o parágrafo culposo está revogado.', 'Distinguir a concessão irregular do art. 67 da informação falsa do art. 66.'],
 'Não ensinar o antigo parágrafo culposo como modalidade atual. A Lei 15.190 tem vacância e controle constitucional em acompanhamento; conferir data do fato e decisão aplicável, sem inferir que ajuizamento suspendeu tudo ou encerrou a controvérsia.',
 'Funcionário concede dolosamente licença que sabe contrariar as normas ambientais, conforme o recorte da redação compilada.',
 'Se a questão indica mera culpa em fato antigo, examinar sucessão de leis e eventual lei mais benéfica; não restaurar automaticamente o parágrafo revogado nem concluir licitude universal de toda conduta.',
 ['A redação compilada mantém modalidade culposa expressa no parágrafo? Não; ele está revogado.', 'Uma notícia de ajuizamento decide definitivamente a constitucionalidade? Não; andamento e decisão precisam ser consultados.'],
 'Concessão dolosa','Concessão consciente no recorte expresso da redação modificadora de 2025.')
add('art-68','O artigo pune a omissão de obrigação de relevante interesse ambiental por quem tem dever legal ou contratual de cumpri-la. O dever específico e sua fonte são requisitos; não basta atribuir genericamente a todos a mesma obrigação.',
 ['Dolo: detenção de 1 a 3 anos E multa.', 'Culpa: detenção de 3 meses a 1 ano, sem prejuízo da multa.', 'O dever pode ser legal OU contratual.'],
 'Não equiparar obrigação moral genérica ao dever específico do tipo. Identificar o conteúdo relevante e a responsabilidade do sujeito no fato.',
 'O responsável deixa de cumprir obrigação ambiental relevante expressamente assumida em contrato, preenchidos os elementos do tipo.',
 'Se o fato é culposo, a resposta usa a pena específica do parágrafo; se falta o dever legal/contratual, não se presume seu preenchimento.',
 ['Só dever previsto em lei pode integrar o tipo? Não; também o contratual.', 'A culpa tem a mesma pena de 1 a 3 anos? Não; o parágrafo prevê 3 meses a 1 ano, sem prejuízo da multa.'],
 'Dever específico','Obrigação ambiental relevante de fonte legal ou contratual atribuída ao sujeito.')
add('art-69','Pune obstruir ou dificultar fiscalização do Poder Público em matéria ambiental. A conduta deve interferir na ação fiscalizadora; não se confunde com qualquer divergência ou com a apresentação regular de defesa no procedimento.',
 ['Pena: detenção de 1 a 3 anos E multa.', 'Obstar OU dificultar: não exige sempre impedir completamente a fiscalização.'],
 'Exercício regular de defesa não é, por si só, embaraço criminoso. O enquadramento depende da ação concreta e dos elementos do tipo.',
 'O agente realiza conduta que dificulta concretamente a fiscalização ambiental, preenchidos os elementos legais.',
 'Apresentar impugnação regular no processo administrativo não se transforma automaticamente na obstrução deste artigo.',
 ['É indispensável impedir completamente a ação? Não; dificultar também é verbo previsto.', 'Toda defesa administrativa configura o crime? Não; defesa regular e obstrução concreta são situações distintas.'],
 'Ação fiscalizadora','Atividade de fiscalização ambiental do Poder Público protegida pelo tipo.')
add('art-69-a','A norma pune elaboração ou apresentação de estudo, laudo ou relatório ambiental total ou parcialmente falso ou enganoso em procedimentos administrativos indicados. Abrange omissão, modalidade culposa e aumento quando a informação causa dano significativo.',
 ['Dolo: reclusão de 3 a 6 anos E multa; culpa: detenção de 1 a 3 anos.', 'Dano significativo decorrente do uso da informação: aumento de 1/3 a 2/3.', 'Inclui licenciamento, concessão florestal OU outro procedimento administrativo.'],
 'Para o aumento, demonstrar dano significativo e o nexo com o uso da informação. Divergência técnica honesta não autoriza presumir falsidade ou culpa penal automaticamente.',
 'É apresentado relatório ambiental parcialmente falso por omissão relevante no licenciamento.',
 'Se há dano significativo decorrente do uso dessa informação, examinar o aumento; não aplicá-lo apenas porque o relatório foi falso, sem demonstrar o resultado e o vínculo.',
 ['A falsidade precisa abranger todo o documento? Não; pode ser parcial e inclusive por omissão.', 'Aumento depende só da existência de informação falsa? Não; exige dano significativo decorrente de seu uso.'],
 'Nexo do uso da informação','Vínculo entre o uso da informação falsa/incompleta/enganosa e o dano significativo do §2º.')
add('art-70','Define infração administrativa ambiental e estabelece competências e garantias de apuração. Qualquer pessoa pode representar, mas lavrar auto e instaurar processo dependem das autoridades indicadas; contraditório e ampla defesa são assegurados.',
 ['Ação OU omissão que viole as regras ambientais descritas pode constituir infração administrativa.', 'Funcionários ambientais do SISNAMA designados para fiscalização e agentes das Capitanias dos Portos são indicados no §1º.', 'Conhecimento da infração impõe apuração imediata por processo próprio.'],
 'Representação particular não equivale a auto de infração lavrado por autoridade. Infração administrativa e crime são regimes distintos; não concluir responsabilidade objetiva de multa a partir da definição geral.',
 'Um cidadão comunica infração à autoridade competente por representação.',
 'Ele tenta aplicar a multa por conta própria: a faculdade de representar não lhe transfere competência sancionatória.',
 ['Qualquer pessoa pode representar? Sim; o §2º permite essa comunicação às autoridades.', 'A apuração dispensa defesa? Não; o §4º assegura ampla defesa e contraditório.'],
 'Representação','Comunicação de possível infração à autoridade para exercício do poder de polícia, não aplicação privada de sanção.')
add('art-71','O processo administrativo ambiental tem prazos máximos legais diferentes para defesa, julgamento, recurso e pagamento. Cada prazo tem seu marco próprio; não se deve tratar todos como contados da mesma data ou misturá-los a prazos penais.',
 ['Defesa: 20 dias da ciência; julgamento: 30 dias da lavratura do auto, apresentada defesa ou não.', 'Recurso: 20 dias na hipótese do inciso III; pagamento: 5 dias do recebimento da notificação.', 'O texto qualifica os prazos como máximos; conferir o procedimento regulamentar aplicável.'],
 'Não concluir arquivamento ou nulidade automática de todo processo pelo simples transcurso de prazo de julgamento. Efeitos do atraso, regras de contagem e regulamentos exigem análise própria.',
 'A questão conta o prazo de defesa de 20 dias desde a lavratura, embora a ciência do autuado tenha ocorrido depois.',
 'Se a pergunta é o prazo de julgamento, o inciso II usa a lavratura do auto, independentemente da apresentação da defesa.',
 ['A defesa começa necessariamente na lavratura? Não; o inciso I usa a ciência da autuação.', 'Pagamento e recurso têm o mesmo prazo legal? Não; os incisos indicam 5 e 20 dias, respectivamente.'],
 'Marco de contagem','Evento legal que inicia o prazo específico, diferente conforme a etapa.')
add('art-72','A lei enumera sanções administrativas e regras de sua aplicação, como cumulação para infrações simultâneas, multa diária para conduta prolongada e possibilidade de conversão da multa simples. Sanção administrativa não se confunde com pena criminal.',
 ['Infrações simultâneas distintas: sanções correspondentes aplicadas cumulativamente (§1º).', 'Multa simples PODE ser convertida em serviços ambientais; a conversão não é automática (§4º).', 'Multa diária: infração prolongada no tempo (§5º); sanções restritivas têm lista própria (§8º).'],
 'Não ensinar multa administrativa como responsabilidade objetiva só pela condição de proprietário. Também não exigir advertência prévia para toda e qualquer multa a partir de uma leitura isolada do §3º. Apreensão/destinação precisam observar o art. 25 e os alertas judiciais preservados.',
 'O autuado sustenta que toda multa simples deve automaticamente ser convertida em serviços.',
 'Se a infração se prolonga no tempo, examinar a multa diária e seus requisitos, sem substituir automaticamente a identificação da conduta pela simples passagem do tempo.',
 ['Conversão da multa é automática pelo §4º? Não; o dispositivo diz pode ser convertida.', 'Uma só sanção exclui sempre todas as outras? Não; há regras de cumulação e cada hipótese precisa ser identificada.'],
 'Multa diária','Sanção vinculada à infração prolongada no tempo, com sua aplicação e requisitos pertinentes.')
add('art-73','Na redação de 2023, o produto das multas ambientais tem destinação aos fundos indicados conforme o órgão arrecadador. Para multas aplicadas pela União, o §1º estabelece percentual para o Fundo Nacional do Meio Ambiente, com possibilidade expressa de alteração.',
 ['A lista inclui FNMA, Fundo Naval, Funcap e fundos estaduais/municipais ambientais ou correlatos.', '50% das multas da União revertem ao FNMA, percentual que pode ser alterado a critério dos órgãos arrecadadores.', 'O §2º está vetado.'],
 'Não apresentar 50% como percentual imutável nem aplicá-lo indistintamente a toda multa estadual ou municipal. É destinação da arrecadação, não desconto ao infrator.',
 'Uma questão afirma que 50% de todas as multas de qualquer ente são desconto obrigatório ao infrator.',
 'Tratando-se de multas da União, o §1º descreve destinação ao FNMA, com a ressalva de alteração do percentual, não abatimento do débito.',
 ['A regra de 50% é um desconto na multa? Não; é destinação de valores arrecadados.', 'O percentual é declarado imutável? Não; o §1º admite alteração a critério dos órgãos arrecadadores.'],
 'Destinação da arrecadação','Destino dos valores recebidos, distinto da apuração ou redução da multa devida.')
add('art-74','A base da multa pode ser unidade, hectare, metro cúbico, quilograma ou outra medida pertinente ao objeto jurídico lesado. A unidade de cálculo depende da infração e não se limita a hectares de área.',
 ['As medidas indicadas são exemplos de base pertinente.', 'Escolher unidade de medida não determina sozinho o valor monetário da sanção.'],
 'Não inventar tarifa universal por hectare ou quilograma a partir deste artigo. O enquadramento e o regulamento aplicável definem o cálculo concreto.',
 'A infração tem objeto mensurado em quilogramas e a questão afirma que a lei só permite hectares.',
 'Se o objeto é uma área, hectare pode ser medida pertinente, mas não é a única medida legal nem define sozinho a tarifa.',
 ['A lista admite outra medida pertinente? Sim; a redação contém essa alternativa.', 'O artigo fixa valor universal por hectare? Não; trata da base de medida, não dessa tarifa.'],
 'Base da multa','Unidade ou medida pertinente usada no cálculo conforme o objeto jurídico lesado.')
add('art-75','O valor da multa administrativa é fixado no regulamento e corrigido periodicamente na forma legal. O artigo apresenta limites gerais, sem atribuir automaticamente o máximo a toda infração nem confundir multa administrativa com dias-multa penal.',
 ['Limites textuais: mínimo de R$ 50 e máximo de R$ 50 milhões.', 'Fixação no regulamento e correção periódica conforme os índices pertinentes.'],
 'Valores do artigo não substituem a faixa específica do regulamento, a motivação e os critérios de aplicação. Não usar esses limites como número de dias-multa criminal.',
 'A questão afirma que toda infração administrativa ambiental recebe automaticamente multa de R$ 50 milhões.',
 'A existência do teto não determina o valor concreto; enquadramento, regulamento e critérios aplicáveis devem ser observados.',
 ['O artigo indica teto de R$ 50 milhões? Sim; como limite textual, não como multa universal.', 'Os limites são contagem de dias-multa penal? Não; pertencem à multa administrativa deste capítulo.'],
 'Teto da multa','Limite máximo textual, que não equivale ao valor obrigatório de toda sanção.')
add('art-79-a','Órgãos ambientais competentes podem celebrar termo de compromisso com força de título executivo extrajudicial para correção de atividades. O instrumento tem cláusulas e publicidade obrigatórias; os parágrafos com datas de 1998 são transição histórica, não reabertura permanente de prazo.',
 ['Vigência do compromisso: 90 dias a 3 anos, prorrogável por igual período, conforme complexidade.', 'Descumprimento: rescisão de pleno direito, ressalvados caso fortuito/força maior.', 'Publicação do extrato oficial é requisito de eficácia; multas anteriores não são apagadas pela celebração.'],
 'Os §§2º e 3º vinculam sua hipótese a empreendimentos e requerimentos datados de 1998. Não ensinar suspensão universal de sanções por todo termo novo, nem transformar o prazo histórico em janela aberta em 2026.',
 'Um termo para correção de atividade é celebrado sem publicação do extrato no órgão oficial competente.',
 'Após publicação, ainda se observam as cláusulas e a execução de multas anteriores; o termo não elimina automaticamente todos os débitos ou responsabilidade penal.',
 ['Sem publicação do extrato há eficácia pelo §8º? Não; a publicação é exigida sob pena de ineficácia.', 'Celebrar qualquer termo novo suspende universalmente todas as sanções? Não; a hipótese dos §§2º e 3º tem transição histórica específica, e o §4º preserva execução de multas anteriores.'],
 'Título executivo extrajudicial','Força atribuída ao termo para exigibilidade das obrigações, observados seus requisitos legais.')

